{{-- Trust bar pembayaran Indonesia: QRIS / VA / COD / Retur --}}
<section class="bg-stone-900 text-stone-200 py-4" aria-label="Jaminan belanja">
    <div class="max-w-7xl mx-auto px-4 flex items-center gap-2 overflow-x-auto whitespace-nowrap text-xs scrollbar-none" style="scrollbar-width:none">
        <span class="inline-flex items-center gap-1.5 px-3 py-1.5 bg-white/10 rounded-full"><i class="fas fa-qrcode text-green-400"></i> QRIS instan</span>
        <span class="inline-flex items-center gap-1.5 px-3 py-1.5 bg-white/10 rounded-full"><i class="fas fa-university text-blue-300"></i> VA BCA · Mandiri · BNI · BRI</span>
        <span class="inline-flex items-center gap-1.5 px-3 py-1.5 bg-white/10 rounded-full"><i class="fas fa-wallet text-amber-300"></i> GoPay · OVO · DANA</span>
        <span class="inline-flex items-center gap-1.5 px-3 py-1.5 bg-white/10 rounded-full"><i class="fas fa-money-bill-wave text-emerald-300"></i> COD tersedia</span>
